INSERT INTO public.documents (id, title, body, author_email, internal_notes) VALUES
    (1, 'Replication slots and disk usage', 'A logical replication slot keeps every WAL segment its consumer has not confirmed. If the consumer stops, the primary keeps that WAL forever unless max_slot_wal_keep_size invalidates the slot, so monitor retained WAL and free disk space.', 'author1@example.invalid', 'internal note 1'),
    (2, 'Choosing a primary key', 'Stable primary keys make change data capture simple. Natural keys that change force downstream systems to treat an update as a delete followed by an insert.', 'author2@example.invalid', 'internal note 2'),
    (3, 'Sourdough starter basics', 'A sourdough starter is a culture of wild yeast and lactic acid bacteria. Feed it equal weights of flour and water daily and keep it at room temperature until it doubles within six hours.', 'author3@example.invalid', 'internal note 3'),
    (4, 'Proofing bread dough', 'Dough is proofed when it has grown by about half and springs back slowly when pressed. Cold proofing overnight in the refrigerator develops a more sour, complex flavour.', 'author4@example.invalid', 'internal note 4'),
    (5, 'Watering tomato plants', 'Tomatoes prefer deep watering two or three times a week rather than a little every day. Water at the base to keep leaves dry and reduce fungal blight.', 'author5@example.invalid', 'internal note 5'),
    (6, 'Pruning fruit trees', 'Prune apple and pear trees in late winter while they are dormant. Remove dead, crossing and inward-growing branches to open the canopy to light and air.', 'author6@example.invalid', 'internal note 6'),
    (7, 'Observing Jupiter''s moons', 'Through a small telescope the four Galilean moons look like bright points lined up beside Jupiter. Their positions change from night to night as they orbit the planet.', 'author7@example.invalid', 'internal note 7'),
    (8, 'What is a light-year', 'A light-year is the distance light travels in one year, about 9.46 trillion kilometres. It measures distance, not time.', 'author8@example.invalid', 'internal note 8'),
    (9, 'Training for a first marathon', 'Most beginner marathon plans last sixteen to twenty weeks and build a weekly long run gradually. Rest days and easy runs matter as much as the long run.', 'author9@example.invalid', 'internal note 9'),
    (10, 'Recovering after a long run', 'Refuel with carbohydrates and protein within an hour of a long run, rehydrate, and keep moving gently. Soreness that lasts more than a few days may signal overtraining.', 'author10@example.invalid', 'internal note 10'),
    (11, 'Packing light for travel', 'Choose clothes that layer and share a colour palette so every item matches. A carry-on bag avoids lost luggage and speeds up airport connections.', 'author11@example.invalid', 'internal note 11'),
    (12, 'Jet lag strategies', 'Shift your sleep schedule toward the destination time zone a few days before flying. Morning daylight after eastward travel helps reset the body clock.', 'author12@example.invalid', 'internal note 12'),
    (13, 'Index types in PostgreSQL', 'B-tree indexes serve equality and range queries, GIN suits full-text search and arrays, and HNSW from pgvector accelerates approximate nearest-neighbour search on embeddings.', 'author13@example.invalid', 'internal note 13'),
    (14, 'HNSW recall and speed', 'An HNSW graph trades recall for speed. Raising ef_search visits more candidates and improves recall at the cost of higher query latency.', 'author14@example.invalid', 'internal note 14'),
    (15, 'Vacuum and table bloat', 'PostgreSQL marks updated and deleted rows as dead tuples. Autovacuum reclaims them; long-running transactions and abandoned replication slots can stop it from cleaning up.', 'author15@example.invalid', 'internal note 15'),
    (16, 'Composting kitchen scraps', 'A healthy compost pile balances green material such as vegetable scraps with brown material such as dry leaves. Turn it regularly so it stays aerobic and does not smell.', 'author16@example.invalid', 'internal note 16'),
    (17, 'Growing herbs indoors', 'Basil, parsley and mint grow well on a sunny windowsill. Use pots with drainage holes and let the soil surface dry slightly between waterings.', 'author17@example.invalid', 'internal note 17'),
    (18, 'Making fresh pasta', 'Fresh egg pasta needs only flour and eggs, kneaded until smooth and rested for thirty minutes. Roll it thin and cook it for two to three minutes in salted water.', 'author18@example.invalid', 'internal note 18'),
    (19, 'Knife skills for beginners', 'Hold the knife with a pinch grip on the blade and curl the fingers of your guiding hand. A sharp knife is safer than a dull one because it slips less.', 'author19@example.invalid', 'internal note 19'),
    (20, 'Saving for retirement', 'Starting early lets compound growth do most of the work. Low-cost index funds and automatic contributions keep fees and decision fatigue down.', 'author20@example.invalid', 'internal note 20'),
    (21, 'Building an emergency fund', 'An emergency fund covers three to six months of essential expenses. Keep it in an accessible savings account separate from everyday spending.', 'author21@example.invalid', 'internal note 21'),
    (22, 'Learning a new language', 'Short daily practice beats occasional long sessions. Spaced repetition flashcards and speaking with native speakers accelerate vocabulary and confidence.', 'author22@example.invalid', 'internal note 22'),
    (23, 'Caring for a new puppy', 'Puppies need frequent short meals, plenty of sleep and consistent house training. Early socialisation with people and other dogs prevents fear later in life.', 'author23@example.invalid', 'internal note 23'),
    (24, 'Cat litter box tips', 'Provide one litter box per cat plus one extra, placed in quiet spots. Scoop daily, because cats avoid dirty boxes.', 'author24@example.invalid', 'internal note 24'),
    (25, 'Bird watching at dawn', 'Birds are most active and vocal shortly after sunrise. Learning a few common songs helps you identify species you cannot see.', 'author25@example.invalid', 'internal note 25'),
    (26, 'Changing a bicycle tyre', 'Release the brake, remove the wheel, lever the tyre off the rim and replace the tube. Check the inside of the tyre for the thorn or glass that caused the puncture.', 'author26@example.invalid', 'internal note 26'),
    (27, 'Winter car maintenance', 'Check tyre pressure, battery health and antifreeze before winter. Keep an ice scraper, blanket and phone charger in the car.', 'author27@example.invalid', 'internal note 27'),
    (28, 'Writing clear commit messages', 'A good commit message has a short summary line and a body that explains why the change was made. Future readers need the reasoning, not a restatement of the diff.', 'author28@example.invalid', 'internal note 28'),
    (29, 'Code review etiquette', 'Review the change, not the author. Ask questions, explain the reason behind a suggestion, and approve when the code is better than before even if it is not perfect.', 'author29@example.invalid', 'internal note 29'),
    (30, 'Idempotent writes', 'An idempotent operation produces the same result when applied twice. Upserts keyed by a stable identifier let a pipeline replay messages after a crash without duplicates.', 'author30@example.invalid', 'internal note 30'),
    (31, 'Watermarks in change data capture', 'A backfill can run while writes continue by bracketing each snapshot chunk with low and high watermarks in the change stream. Rows changed inside the window are taken from the stream instead of the snapshot.', 'author31@example.invalid', 'internal note 31'),
    (32, 'Meditation for beginners', 'Sit comfortably, focus on the breath and gently return attention when the mind wanders. Five minutes a day is enough to start.', 'author32@example.invalid', 'internal note 32'),
    (33, 'Sleep hygiene', 'Keep a regular sleep schedule, a dark cool bedroom and screens out of bed. Caffeine late in the day delays sleep onset for many people.', 'author33@example.invalid', 'internal note 33'),
    (34, 'Stretching after exercise', 'Static stretches held for twenty to thirty seconds improve flexibility when muscles are warm. Never bounce into a stretch.', 'author34@example.invalid', 'internal note 34'),
    (35, 'Planting spring bulbs', 'Plant tulips and daffodils in autumn, pointed end up, at a depth of about three times the bulb''s height. They need a cold period to flower in spring.', 'author35@example.invalid', 'internal note 35'),
    (36, 'Brewing pour-over coffee', 'Use freshly ground beans, water just off the boil and a ratio of about one gram of coffee to sixteen grams of water. Pour slowly in circles and aim for a three-minute brew.', 'author36@example.invalid', 'internal note 36'),
    (37, 'Steeping green tea', 'Green tea turns bitter in boiling water. Steep it at around 75 to 80 degrees Celsius for one to two minutes.', 'author37@example.invalid', 'internal note 37'),
    (38, 'Solar eclipses', 'A total solar eclipse happens when the Moon completely covers the Sun''s disk. Never look at the partial phases without certified eclipse glasses.', 'author38@example.invalid', 'internal note 38'),
    (39, 'The phases of the Moon', 'The Moon''s phases come from the changing angle between the Sun, Earth and Moon. A full cycle from new moon to new moon takes about 29.5 days.', 'author39@example.invalid', 'internal note 39'),
    (40, 'Hiking safety', 'Tell someone your route and expected return time, carry water, layers and a map, and turn back if the weather turns. Most rescues involve hikers who pushed on.', 'author40@example.invalid', 'internal note 40'),
    (41, 'Camping with kids', 'Pick a campsite with toilets and short walks nearby. Practise setting up the tent at home and bring familiar snacks and a favourite toy.', 'author41@example.invalid', 'internal note 41'),
    (42, 'Retrieval evaluation metrics', 'Recall at ten measures how many relevant documents appear in the top ten results. nDCG also rewards placing relevant documents near the top of the ranking.', 'author42@example.invalid', 'internal note 42'),
    (43, 'Embedding model migrations', 'Switching embedding models changes every vector, so documents must be re-embedded. Building the new index alongside the old one and comparing retrieval quality avoids downtime and regressions.', 'author43@example.invalid', 'internal note 43'),
    (44, 'Freshness of search indexes', 'Users notice when a search index lags behind the database. Measure the time from a committed change to the moment it becomes searchable, and alert when it exceeds a target.', 'author44@example.invalid', 'internal note 44'),
    (45, 'Painting a room', 'Wash and repair walls, tape the trim, and apply primer over patches. Two thin coats of paint look better than one thick coat.', 'author45@example.invalid', 'internal note 45'),
    (46, 'Fixing a leaking tap', 'Most dripping taps need a new washer or cartridge. Turn off the water supply under the sink before taking the tap apart.', 'author46@example.invalid', 'internal note 46'),
    (47, 'Houseplant light needs', 'Snake plants and pothos tolerate low light, while succulents and cacti need several hours of direct sun. Yellowing leaves often mean overwatering rather than too little light.', 'author47@example.invalid', 'internal note 47'),
    (48, 'Writing a cover letter', 'Address the hiring manager by name, connect your experience to two or three requirements of the role, and keep it under one page.', 'author48@example.invalid', 'internal note 48')
