-- Demo source table and a small seeded dataset (written for this project, CC0).
-- author_email and internal_notes are deliberately NOT allowlisted: they are
-- excluded from the publication column list and never reach embedsync.
CREATE TABLE IF NOT EXISTS public.documents (
    id             bigint PRIMARY KEY,
    title          text NOT NULL,
    body           text NOT NULL,
    author_email   text,
    internal_notes text,
    updated_at     timestamptz NOT NULL DEFAULT now()
);

ON CONFLICT (id) DO NOTHING;
